"""One toy-host campaign, declared and assembled — the input an analysis memo is generated over.

Whether the memo is generated by a fixtured completion or by a real model, everything up to the
call is the same campaign, so it is built once here.

**The sweep is one axis with two levels, and the apparatus is held still under it.** A confound
would be a legitimate thing to generate a memo about, but it is not what this campaign is for — a
memo over a clean sweep — and a corpus that also moved the reviewer pool would make every refusal
ambiguous between the two.
"""

from __future__ import annotations

from collections.abc import Sequence
from typing import TypedDict

from threetears.evals.analysis import AnalysisContextBundle, assemble_context_bundle
from threetears.evals.kernel import (
    Aspect,
    AspectDesign,
    BarOverride,
    CampaignArm,
    ControlDeclaration,
    EvalCampaign,
    IDENTITY_VERSION,
    EvalInsight,
    SweptAxis,
)
from threetears.evals.kernel.host import HostProfile
from threetears.evals.schema import IntervalScale, SweepableValue
from packages.evals.tests.fixtures.toyhost.profile import toyhost_profile
from packages.evals.tests.fixtures.toyhost.corpus import (
    TOYHOST_GRADER_VERSION,
    TOYHOST_INSTANT,
    TOYHOST_SCOPE,
    TOYHOST_SUBJECT,
    ToyhostStorage,
    toyhost_batch,
    toyhost_measurements,
)

#: The one question the campaign asks of its arms, in the operator's words.
TOYHOST_QUESTION = "is the wider chunk worth what it costs to retrieve?"

#: The axis swept, spelled as the toy host's registry spells it. A declared axis is a name the
#: host ACCEPTS — a registered sweepable LEVER, or a member of an open family its own membership
#: test recognises. This one is a fixed lever.
TOYHOST_AXIS = "chunk_tokens"

#: The two levels, narrow first. Both are declared, so a memo silent about either is refused
#: rather than merely incomplete.
TOYHOST_NARROW = 256
TOYHOST_WIDE = 1024


#: What each arm measured. The wider chunk is dearer and slower AND more accurate, which is what
#: makes the declared question a real trade rather than a foregone one: ~17% more accuracy for 50%
#: more spend and 55% more wall-clock is a judgement, and a reader has to make it. An arm that won
#: on every axis would leave nothing to weigh, and the memo would be a restatement of the table.
#: The reviewer pool scored the wider chunk a point higher on layout fidelity too, so the judged
#: half of the trade agrees with the measured one — and neither is a ranking measure.
class _ArmMeasurements(TypedDict):
    cost_usd: float
    total_ms: float
    field_accuracy: float
    layout_fidelity: int


_MEASUREMENTS: dict[int, _ArmMeasurements] = {
    TOYHOST_NARROW: {"cost_usd": 0.02, "total_ms": 900.0, "field_accuracy": 0.78, "layout_fidelity": 3},
    TOYHOST_WIDE: {"cost_usd": 0.03, "total_ms": 1400.0, "field_accuracy": 0.91, "layout_fidelity": 4},
}

#: How much context each arm carried into extraction, per document — the mechanism ``chunk_tokens``
#: declares it acts on (``acts_on="context_tokens_in"``). Wider chunks carry more, by one amount on every
#: document: a token count declares no range, and no test of the mean can call a move of one amount with no
#: range (#597), so the bundle's check on that lever reads ``unchecked`` for ``uniform_move_needs_range``,
#: never ``moved`` on a test that asks about symmetry rather than the mean.
_CONTEXT_TOKENS_IN: dict[int, int] = {TOYHOST_NARROW: 2_400, TOYHOST_WIDE: 7_600}

#: The spend ceiling the campaign holds itself to, per document. Between the two arms' spend on
#: purpose, so the bar has one arm on each side of it: a bar every arm clears, or every arm fails,
#: cannot show that the verdict was computed rather than defaulted. Lower-is-better, the direction
#: the host's registered bars exercise only once.
TOYHOST_COST_BAR_USD = 0.025


def toyhost_aspect_design(**changes: object) -> AspectDesign:
    """What the toy-host campaign's one aspect set out to vary and hold itself to.

    :param changes: Fields of the design to change first (``bars``, ...).
    :ptype changes: object
    :return: The design: one interval-scaled axis at two levels, a spend bar, and ``held_fixed`` recording that the
        stimulus was never held — documents arrive from live intake, the observational shape rather than a
        commissioned one. ``merit_axes`` is empty: the campaign's question is unscoped.
    :rtype: AspectDesign
    """
    design = AspectDesign(
        axes=[
            SweptAxis(
                axis_id=TOYHOST_AXIS,
                values=[
                    SweepableValue.of(level, scale=IntervalScale(value=level, unit="tok"), keep_raw=True)
                    for level in (TOYHOST_NARROW, TOYHOST_WIDE)
                ],
                rationale="does a longer chunk carry the whole field or bury it among its neighbours",
            )
        ],
        # A spend ceiling on an engine-core measure: the host registers bars on its own
        # measures only, so this is the bar the campaign adds rather than tightens.
        bars=[BarOverride(measure_id="cost_usd", threshold=TOYHOST_COST_BAR_USD, direction="lower_is_better")],
        held_fixed=ControlDeclaration(
            stimulus="uncontrolled",
            stimulus_reason="documents arrive from live intake; the vendor mix drifts week to week",
            apparatus="witnessed",
        ),
        merit_axes=[],
    )
    return design.model_copy(update=changes)


def toyhost_campaign_of_one_aspect(
    *,
    design: AspectDesign | None,
    question: str = TOYHOST_QUESTION,
    asked_at: str = TOYHOST_INSTANT,
    control_key: str | None = None,
    template_id: str | None = None,
    run_ids: Sequence[str] = (),
    **fields: object,
) -> EvalCampaign:
    """A toy-host campaign of one aspect, labelled with its behavior, asking one question of its arms.

    The aspect's design, the question and the time it was asked are pinned by the caller (``asked_at`` defaults to
    :data:`TOYHOST_INSTANT`), because a default clock would put a wall-clock leaf into every bundle built from it.

    :param design: The aspect's design; ``None`` declares none.
    :ptype design: AspectDesign | None
    :param question: The one question the campaign asks.
    :ptype question: str
    :param asked_at: When the question was asked in full.
    :ptype asked_at: str
    :param control_key: The variant key of the declared control arm; ``None`` names no arm.
    :ptype control_key: str | None
    :param template_id: The template the aspect's runs were gathered on.
    :ptype template_id: str | None
    :param run_ids: The runs the aspect holds.
    :ptype run_ids: Sequence[str]
    :param fields: The campaign's other fields (``id``, ``scope_id``, ``name``, ``subject_id``, ``behavior`` ...).
    :ptype fields: object
    :return: The campaign.
    :rtype: EvalCampaign
    """
    behavior = str(fields["behavior"])
    declared = design is not None
    return EvalCampaign.model_validate(
        {
            **fields,
            "question": question if declared else "",
            "declared_at": asked_at if declared else None,
            "arms": []
            if control_key is None
            else [
                CampaignArm(label="control", role="control", variant_key=control_key, identity_version=IDENTITY_VERSION)
            ],
            "aspects": [
                Aspect(
                    label=behavior.replace("/", "-"),
                    template_id=template_id,
                    run_ids=list(run_ids),
                    design=design,
                    declared_at=TOYHOST_INSTANT if declared else None,
                    asked_at=asked_at if declared else None,
                )
            ],
        }
    )


def toyhost_campaign(
    *,
    grader_versions: tuple[str, str] | None = None,
    insights: Sequence[EvalInsight] = (),
    profile: HostProfile | None = None,
) -> tuple[EvalCampaign, ToyhostStorage]:
    """The declared campaign and the store holding what it observed.

    :param grader_versions: The grader version each arm recorded, narrow then wide. ``None`` leaves
        both at the fixture default, which is the ordinary campaign — two arms that share
        their rig. Supplying two different versions moves a host dimension pinned into the
        engine's ``judge`` role, which is the condition the role disclosure and the
        ``roles_differ`` badge exist to catch and the only way to assemble a BUNDLE carrying
        it. Kept as a parameter rather than a second fixture so both shapes come from one
        builder and cannot drift apart.
    :ptype grader_versions: tuple[str, str] | None
    :param insights: The subject's prior ledger, held by the store. Empty by default — the toy host
        has generated nothing before.
    :ptype insights: Sequence[EvalInsight]
    :param profile: The host the batches ran under, which keys their observations. ``None`` is
        :func:`toyhost_profile`.
    :ptype profile: HostProfile | None
    :return: The campaign — no template, no battery, an extractor configuration for a subject — and the
        storage double its two batches live in.
    :rtype: tuple[EvalCampaign, ToyhostStorage]
    """
    graders = grader_versions or (TOYHOST_GRADER_VERSION, TOYHOST_GRADER_VERSION)
    batches = [
        toyhost_batch(
            chunk_tokens=level,
            retriever_top_k=3,
            extraction_schema="v1",
            ocr_engine_version="tess-5.3.1",
            reviewer_pool="pool-a",
            grader_version=grader,
        )
        for level, grader in zip((TOYHOST_NARROW, TOYHOST_WIDE), graders, strict=True)
    ]
    storage = ToyhostStorage(
        batches,
        {
            batch.id: toyhost_measurements(
                batch,
                profile=profile if profile is not None else toyhost_profile(),
                covariates={"context_tokens_in": _CONTEXT_TOKENS_IN[level]},
                **_MEASUREMENTS[level],
            )
            for batch, level in zip(batches, (TOYHOST_NARROW, TOYHOST_WIDE), strict=True)
        },
        insights,
    )
    campaign = toyhost_campaign_of_one_aspect(
        # Pinned for the same reason the batches are: `EvalCampaign.id` defaults
        # to `uuid4`, so the campaign this fixture assembles was a different
        # campaign every call and no two bundles could fingerprint alike.
        id="2d5b8a41-0e37-4c96-b8f2-7a6d9e415c03",
        scope_id=TOYHOST_SCOPE,
        name="chunk width sweep",
        subject_id=TOYHOST_SUBJECT.subject_id,
        subject_kind="extractor_config",
        behavior="extract_invoice_fields",
        # Absent on purpose, both of them: the toy host commissions nothing, so it has no template
        # to name and no battery to reference. A bundle that needed either would be one only a
        # commissioned host could assemble.
        template_id="",
        run_ids=[batch.id for batch in batches],
        design=toyhost_aspect_design(),
        created_by="test:fixture",
    )
    return campaign, storage


def toyhost_bundle(
    *, grader_versions: tuple[str, str] | None = None, profile: HostProfile | None = None
) -> AnalysisContextBundle:
    """The assembled context one toy-host memo is generated over.

    Assembled in the toy host's vocabulary: the assembler resolves apparatus and variant identity
    through the profile it is handed, and the corpus is written in this one's.

    :param grader_versions: Passed through to :func:`toyhost_campaign`. The default is the committed
        bundle the paid capture answers; supplying two versions is how a test reaches an
        assembled bundle whose grader moved.
    :ptype grader_versions: tuple[str, str] | None
    :param profile: The profile to assemble under. ``None`` is :func:`toyhost_profile`; a test passes
        a variant of it to hold one declaration to another value.
    :ptype profile: HostProfile | None
    :return: The bundle.
    :rtype: AnalysisContextBundle
    """
    host = profile if profile is not None else toyhost_profile()
    campaign, storage = toyhost_campaign(grader_versions=grader_versions, profile=host)
    return assemble_context_bundle(campaign, storage=storage, profile=host)


__all__ = [
    "TOYHOST_AXIS",
    "TOYHOST_COST_BAR_USD",
    "TOYHOST_NARROW",
    "TOYHOST_QUESTION",
    "TOYHOST_WIDE",
    "toyhost_bundle",
    "toyhost_campaign",
    "toyhost_campaign_of_one_aspect",
    "toyhost_aspect_design",
]
